}

func (a DurableEmails) EnqueueEmail(ctx context.Context, input DurableEmail) (DurableEmailResult, error) {
	stored, err := a.Module.EnqueueEmail(ctx, deliveryContract.EmailIntent{TenantID: input.TenantID, Template: input.Template, Recipient: deliveryContract.EmailRecipient{Address: input.Recipient}, Payload: input.Payload, IdempotencyKey: input.IdempotencyKey, Related: deliveryContract.RelatedEntity{Type: input.RelatedType, ID: input.RelatedID}, DeliverAfter: input.DeliverAfter})
	if err != nil {
		return DurableEmailResult{}, err
	}
	return DurableEmailResult{ID: stored.ID, Duplicate: stored.Duplicate}, nil
}

func (s *Service) CancelPendingByRelatedEntity(ctx context.Context, relatedType string, relatedID int64, reason string) (int64, error) {
	if s == nil || s.delivery == nil {
		return 0, errors.New("outbox service not wired")
	}
	tenantID, err := tenant.TenantFromContext(ctx)
	if err != nil {
		return 0, fmt.Errorf("cancel email outbox rows: tenant is required: %w", err)
	}
	return s.delivery.CancelEmail(ctx, tenantID.Int64(), relatedType, relatedID, reason)
}

