func (s *preferenceService) DisableAllForParent(ctx context.Context, accountID int64) error {
	ctx = s.withTenantRuntime(ctx)
	if accountID <= 0 {
		return errors.New("account id is required")
	}
	return s.forEachGuardianTenant(ctx, accountID, func(tenantCtx context.Context, tenantID int64) error {
		if err := s.consent.DisableConsent(tenantCtx, accountID, typeKeysForPortal(PortalParent)); err != nil {
			return fmt.Errorf("disable notification preferences for tenant %d: %w", tenantID, err)
		}
		return nil
	})
}

func (s *preferenceService) DisableAllForPortalAccount(ctx context.Context, accountID int64, portal string) error {
	if accountID <= 0 {
		return errors.New("account id is required")
	}
	if portal != PortalStaff && portal != PortalSchool {
		return fmt.Errorf("unsupported preference portal %q", portal)
	}
	if err := s.consent.DisableConsent(ctx, accountID, typeKeysForPortal(portal)); err != nil {
		return fmt.Errorf("disable notification preferences: %w", err)
	}
	return s.declineDefaultOnTypes(ctx, accountID, portal)
}

func (s *preferenceService) EmailSubscribed(ctx context.Context, accountID int64, permissions []string, notificationType string) (bool, error) {
	if err := s.checkOwnEmailDecision(accountID, permissions, notificationType); err != nil {
		return false, err
	}
	stored, err := s.consent.StoredConsent(ctx, accountID)
	if err != nil {
		return false, fmt.Errorf("load e-mail subscription: %w", err)
	}
	return stored[notificationType], nil
}

func (s *preferenceService) SetEmailSubscribed(ctx context.Context, accountID int64, permissions []string, notificationType string, enabled bool) error {
	if err := s.checkOwnEmailDecision(accountID, permissions, notificationType); err != nil {
		return err
	}
	if err := s.consent.RecordConsent(ctx, accountID, notificationType, enabled); err != nil {
		return fmt.Errorf("save e-mail subscription: %w", err)
	}
	return nil
}

